            register_write_lock(&lock_path);
            return Ok(WriteLock { _inner: None, lock_path });
        }
        let inner = FileLock::acquire_blocking(&lock_path)?;
        register_write_lock(&lock_path);
        Ok(WriteLock { _inner: Some(inner), lock_path })
